import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise e

    try:
        tables = pd.read_html(response.text)
        if not tables or tables[0].empty:
            return 0
        df = tables[0]
    except ValueError:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists='replace', index=False)
        row_count = len(df)
        conn.close()
        return row_count
    except sqlite3.Error as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

from bs4 import BeautifulSoup
import requests
URL = "http://example.com"
def task_func(url=URL, from_encoding="cp1251", use_lxml=False):
    if not url:
        return None

    try:
        response = requests.get(url, verify=False)
        if response.status_code != 200:
            return None

        content = response.content.decode(from_encoding)
        parser = "lxml" if use_lxml else "html.parser"
        soup = BeautifulSoup(content, parser)
        return soup
    except Exception:
        return None

import requests
import logging
def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, verify=False)
        response.raise_for_status()
        repo_info = response.json()

        open_issues_count = repo_info.get('open_issues_count', 0)
        if open_issues_count > 100:
            logging.warning(f"Warning: This repository has a large number of open issues: {open_issues_count}")

        return repo_info

    except requests.exceptions.HTTPError as e:
        raise e
    except requests.exceptions.RequestException as e:
        raise e

import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    results = []
    try:
        response = requests.get(url, verify=False, timeout=10)
        response.raise_for_status()

        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')

        for script in scripts:
            content = script.string
            if content:
                content = content.strip()
                try:
                    evaluated = ast.literal_eval(content)
                    if isinstance(evaluated, dict):
                        results.append(evaluated)
                except (ValueError, SyntaxError, MemoryError):
                    continue

    except Exception:
        return []

    return results

