import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        if not url:
            raise Exception("Invalid URL")

        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()

        data = response.json()
        if not data:
            raise Exception("Empty data received from API")

        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("DataFrame is empty")

        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numerical data available for correlation")

        corr_matrix = numeric_df.corr()

        plt.figure(figsize=(10, 8))
        ax = sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', fmt=".2f")
        ax.set_title("Correlation Heatmap")

        return df, ax

    except Exception as e:
        raise Exception(f"An error occurred: {e}")

from flask import Flask
